        "chunk_id": "chunk_lb_d4_0062",
        "item_number": 62,
        "category": "dialogue",
        "english": "R: What do you say?",
        "vietnamese": "R: Ý mày sao?",
        "speaker": "R",
        "audio_url": "https://storage.googleapis.com/chunks-mirror-audio-284566312743/level_b/day_4/chunk_lb_d4_0062.mp3",
