        "chunk_id": "chunk_lb_d4_0073",
        "item_number": 73,
        "category": "dialogue",
        "english": "R: This morning I already asked a local",
        "vietnamese": "R: Sáng nay tao có hỏi một đứa dân địa phương rồi",
        "speaker": "R",
        "audio_url": "https://storage.googleapis.com/chunks-mirror-audio-284566312743/level_b/day_4/chunk_lb_d4_0073.mp3",
