        "chunk_id": "chunk_lb_d4_0074",
        "item_number": 74,
        "category": "dialogue",
        "english": "R: You see that mango tree?",
        "vietnamese": "R: Mày thấy cây xoài đó không?",
        "speaker": "R",
        "audio_url": "https://storage.googleapis.com/chunks-mirror-audio-284566312743/level_b/day_4/chunk_lb_d4_0074.mp3",
        "beat_prosody": null,
